const header=document.querySelector('.site-header');const menu=document.querySelector('#menu');const toggle=document.querySelector('.menu-toggle');if(header&&menu&&toggle){const updateHeader=()=>header.classList.toggle('scrolled',scrollY>20);updateHeader();addEventListener('scroll',updateHeader,{passive:true});toggle.addEventListener('click',()=>{const open=menu.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));});menu.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{menu.classList.remove('open');toggle.setAttribute('aria-expanded','false');}));addEventListener('keydown',event=>{if(event.key==='Escape'&&menu.classList.contains('open')){menu.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.focus();}});}const revealElements=document.querySelectorAll('.reveal');if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}}),{threshold:.12});revealElements.forEach(element=>observer.observe(element));}else{revealElements.forEach(element=>element.classList.add('visible'));}const videos=[...document.querySelectorAll('video')];videos.forEach(video=>video.addEventListener('play',()=>videos.forEach(other=>{if(other!==video)other.pause()})));const track=document.querySelector('.carousel-track');const cards=[...document.querySelectorAll('.testimonial-card')];const dots=document.querySelector('.carousel-dots');const previous=document.querySelector('.carousel-btn.prev');const next=document.querySelector('.carousel-btn.next');if(track&&cards.length&&dots&&previous&&next){let current=0;const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');const select=(index)=>{current=(index+cards.length)%cards.length;cards.forEach((card,number)=>card.classList.toggle('active',number===current));[...dots.children].forEach((dot,number)=>{dot.classList.toggle('active',number===current);dot.setAttribute('aria-current',String(number===current));});};const go=(index,instant=false)=>{select(index);const card=cards[current];const cardRect=card.getBoundingClientRect();const trackRect=track.getBoundingClientRect();track.scrollTo({left:track.scrollLeft+cardRect.left+cardRect.width/2-trackRect.left-track.clientWidth/2,behavior:instant||reducedMotion.matches?'instant':'smooth'});};let scrollFrame=0;const syncSelection=()=>{scrollFrame=0;const trackRect=track.getBoundingClientRect();const center=trackRect.left+track.clientWidth/2;let nearest=0;let distance=Infinity;cards.forEach((card,index)=>{const rect=card.getBoundingClientRect();const delta=Math.abs(rect.left+rect.width/2-center);if(delta<distance){distance=delta;nearest=index;}});if(nearest!==current)select(nearest);};track.addEventListener('scroll',()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(syncSelection);},{passive:true});let drag=null;let suppressClickUntil=0;track.querySelectorAll('img').forEach(image=>{image.draggable=false;});track.addEventListener('dragstart',event=>event.preventDefault());track.addEventListener('pointerdown',event=>{suppressClickUntil=0;if(event.pointerType==='touch'||event.button!==0||!event.isPrimary)return;drag={id:event.pointerId,startX:event.clientX,startScroll:track.scrollLeft,moved:false};});track.addEventListener('pointermove',event=>{if(!drag||event.pointerId!==drag.id)return;const delta=event.clientX-drag.startX;if(!drag.moved&&Math.abs(delta)<6)return;if(!drag.moved){drag.moved=true;track.classList.add('is-dragging');track.setPointerCapture(event.pointerId);}event.preventDefault();track.scrollLeft=drag.startScroll-delta;});const endDrag=event=>{if(!drag||event.pointerId!==drag.id)return;const {id,moved}=drag;drag=null;if(moved){suppressClickUntil=performance.now()+500;syncSelection();track.classList.remove('is-dragging');go(current);}if(track.hasPointerCapture(id))track.releasePointerCapture(id);};track.addEventListener('pointerup',endDrag);track.addEventListener('pointercancel',endDrag);track.addEventListener('lostpointercapture',endDrag);track.addEventListener('pointerleave',event=>{if(drag&&!drag.moved)endDrag(event);});track.addEventListener('click',event=>{if(event.detail!==0&&performance.now()<suppressClickUntil){event.preventDefault();event.stopImmediatePropagation();}},true);cards.forEach((_,index)=>{const button=document.createElement('button');button.type='button';button.setAttribute('aria-label',`Mostrar depoimento ${index+1}`);button.addEventListener('click',()=>go(index));dots.appendChild(button);});previous.addEventListener('click',()=>go(current-1));next.addEventListener('click',()=>go(current+1));track.addEventListener('keydown',event=>{if(event.key==='ArrowLeft'){event.preventDefault();go(current-1);}if(event.key==='ArrowRight'){event.preventDefault();go(current+1);}});go(0,true);if('ResizeObserver'in window){new ResizeObserver(()=>go(current,true)).observe(track);}else{addEventListener('resize',()=>go(current,true));}if(typeof HTMLDialogElement!=='undefined'){const lightbox=document.createElement('dialog');lightbox.className='testimonial-lightbox';lightbox.setAttribute('aria-label','Depoimento ampliado');lightbox.innerHTML='<button type="button" aria-label="Fechar imagem ampliada">×</button><img alt="">';document.body.appendChild(lightbox);const lightboxImage=lightbox.querySelector('img');lightbox.querySelector('button').addEventListener('click',()=>lightbox.close());lightbox.addEventListener('click',event=>{if(event.target===lightbox)lightbox.close()});cards.forEach(card=>{const image=card.querySelector('img');if(!image)return;image.tabIndex=0;image.setAttribute('role','button');image.setAttribute('aria-label',`${image.alt}. Clique para ampliar`);const open=()=>{lightboxImage.src=image.currentSrc||image.src;lightboxImage.alt=image.alt;lightbox.showModal();};image.addEventListener('click',open);image.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open()}});});}}